<script lang="ts">
  import { onMount } from 'svelte';
  import { Activity, ArrowLeft, Database, FileWarning, HardDrive, LayoutDashboard, Search, ShieldCheck, Users } from '@lucide/svelte';
  let { data, form } = $props();
  let activeView = $state<'overview' | 'users' | 'moderation' | 'system'>('overview');
  let liveSystem = $state(data.system);
  let systemMeasuredAt = $state(new Date());
  onMount(() => {
    const refreshSystem = async () => {
      if (activeView !== 'system' || document.hidden) return;
      const response = await fetch('/admin/system', { cache: 'no-store' }).catch(() => null);
      if (!response?.ok) return;
      const snapshot = await response.json();
      liveSystem = snapshot;
      systemMeasuredAt = new Date(snapshot.measuredAt);
    };
    const timer = window.setInterval(refreshSystem, 3000);
    return () => window.clearInterval(timer);
  });
  const formatBytes = (bytes: number) => bytes < 1024 * 1024 ? `${(bytes / 1024).toFixed(1)} KB` : bytes < 1024 ** 3 ? `${(bytes / 1024 ** 2).toFixed(1)} MB` : `${(bytes / 1024 ** 3).toFixed(2)} GB`;
  const formatUptime = (seconds: number) => `${Math.floor(seconds / 86400)}d ${Math.floor(seconds % 86400 / 3600)}t ${Math.floor(seconds % 3600 / 60)}m`;
  const date = (value: Date | null) => value ? value.toLocaleString('nb-NO', { dateStyle: 'short', timeStyle: 'short' }) : 'Aldri';
  const reasonLabels: Record<string, string> = { spam: 'Spam', harassment: 'Trakassering', sexual: 'Seksuelt innhold', violence: 'Vold', privacy: 'Personvern', other: 'Annet' };
</script>

<svelte:head><title>Admin – Samvio</title><meta name="robots" content="noindex,nofollow"/></svelte:head>

<main class="admin-page">
  <aside class="admin-nav">
    <a class="admin-brand" href="/"><span>S</span><div><strong>Samvio</strong><small>Administrasjon</small></div></a>
    <nav aria-label="Adminområder">
      <button class:active={activeView === 'overview'} onclick={() => activeView = 'overview'}><LayoutDashboard size={19}/>Oversikt</button>
      <button class:active={activeView === 'users'} onclick={() => activeView = 'users'}><Users size={19}/>Brukere</button>
      <button class:active={activeView === 'moderation'} onclick={() => activeView = 'moderation'}><FileWarning size={19}/>Moderering{#if data.stats.reports}<span class="count">{data.stats.reports}</span>{/if}</button>
      <button class:active={activeView === 'system'} onclick={() => activeView = 'system'}><Database size={19}/>System</button>
    </nav>
    <a class="back" href="/"><ArrowLeft size={17}/>Tilbake til Samvio</a>
  </aside>

  <section class="admin-content">
    <header class="topbar"><div><span>Samvio kontrollrom</span><h1>{activeView === 'overview' ? 'Oversikt' : activeView === 'users' ? 'Brukerbehandling' : activeView === 'moderation' ? 'Moderering' : 'System og lagring'}</h1><p>Innlogget som {data.admin.realName}</p></div><div class="healthy"><i></i>Systemet kjører</div></header>
    {#if form?.adminError}<div class="notice error" role="alert">{form.adminError}</div>{:else if form?.adminSuccess}<div class="notice success">{form.adminSuccess}</div>{/if}

    {#if activeView === 'overview'}
      <section class="stat-grid">
        <article><span><Activity size={18}/></span><p>Aktive brukere 24t</p><strong>{data.stats.active24}</strong><small>Basert på siste aktivitet</small></article>
        <article><span><Users size={18}/></span><p>Registrerte brukere</p><strong>{data.stats.users}</strong><small>Alle kontoer</small></article>
        <article><span><LayoutDashboard size={18}/></span><p>Totalt antall innlegg</p><strong>{data.stats.posts}</strong><small>Kronologiske øyeblikk</small></article>
        <article class:attention={data.stats.reports}><span><FileWarning size={18}/></span><p>Åpne rapporter</p><strong>{data.stats.reports}</strong><small>Venter på behandling</small></article>
      </section>
      <section class="overview-grid"><article class="panel"><header><div><ShieldCheck size={20}/><h2>Systemstatus</h2></div><span class="status good">Operativ</span></header><div class="status-list"><p><span>Applikasjon</span><strong>På nett</strong></p><p><span>Database</span><strong>Tilkoblet</strong></p><p><span>Bildeopplasting</span><strong>Maks 25 MB</strong></p><p><span>Feed</span><strong>Kronologisk</strong></p></div></article><article class="panel"><header><div><HardDrive size={20}/><h2>Lagring</h2></div><span>{formatBytes(data.storage.bytes)}</span></header><div class="storage-bar"><i style={`width:${Math.min(100, data.storage.bytes / data.storage.limitBytes * 100)}%`}></i></div><p class="muted">{formatBytes(data.storage.bytes)} brukt av omtrent {formatBytes(data.storage.limitBytes)} diskplass.</p></article></section>
    {:else if activeView === 'users'}
      <section class="panel"><header class="table-head"><div><Users size={20}/><h2>Brukere</h2><span>{data.users.length} vist</span></div><form method="GET"><Search size={17}/><input name="q" value={data.query} placeholder="Søk etter navn, @bruker eller e-post"/><button>Søk</button></form></header><div class="table-wrap"><table><thead><tr><th>Bruker</th><th>Medlemskap</th><th>Status</th><th>Sist aktiv</th><th>Rolle</th><th>Handlinger</th></tr></thead><tbody>{#each data.users as user}<tr><td><strong>{user.realName}</strong><small>@{user.username}<br/>{user.email}</small></td><td><span class:subscriber={user.subscriber} class="pill">{user.subscriber ? 'Vipps' : 'Gratis'}</span></td><td><span class:suspended={user.status === 'suspended'} class="pill">{user.status === 'suspended' ? 'Utestengt' : user.mutedUntil && user.mutedUntil > new Date() ? 'Dempet' : 'Aktiv'}</span></td><td>{date(user.lastSeenAt)}</td><td><form method="POST" action="?/userAction" class="role-form"><input type="hidden" name="userId" value={user.id}/><input type="hidden" name="operation" value="role"/><select name="role" aria-label={`Rolle for ${user.realName}`}><option value="user" selected={user.role === 'user'}>Bruker</option><option value="moderator" selected={user.role === 'moderator'}>Moderator</option><option value="admin" selected={user.role === 'admin'}>Admin</option></select><button>Lagre</button></form></td><td><div class="row-actions"><form method="POST" action="?/userAction"><input type="hidden" name="userId" value={user.id}/><input type="hidden" name="operation" value={user.mutedUntil && user.mutedUntil > new Date() ? 'unmute' : 'mute'}/><button>{user.mutedUntil && user.mutedUntil > new Date() ? 'Opphev mute' : 'Mute 24t'}</button></form><form method="POST" action="?/userAction"><input type="hidden" name="userId" value={user.id}/><input type="hidden" name="operation" value={user.status === 'suspended' ? 'unban' : 'ban'}/><button class="danger">{user.status === 'suspended' ? 'Opphev ban' : 'Ban'}</button></form></div></td></tr>{/each}</tbody></table></div></section>
    {:else if activeView === 'moderation'}
      <section class="panel"><header><div><FileWarning size={20}/><h2>Rapportkø</h2></div><span class="pill">{data.reports.length} rapporter</span></header>{#if data.reports.length}<div class="table-wrap"><table><thead><tr><th>Rapport</th><th>Innhold</th><th>Innmelder</th><th>Status</th><th>Handlinger</th></tr></thead><tbody>{#each data.reports as report}<tr><td><strong>{reasonLabels[report.reason]}</strong><small>{report.details || 'Ingen tilleggsinformasjon'}<br/>{date(report.createdAt)}</small></td><td><span class="type">{report.targetType}</span><strong>{report.target?.author || 'Slettet innhold'}</strong><small>{report.target?.text || report.targetId}</small></td><td>{report.reporterName}<small>@{report.reporterUsername}</small></td><td><span class:open={report.status === 'open'} class="pill">{report.status}</span></td><td><div class="row-actions">{#each [['approve','Godkjenn'],['hide','Skjul'],['delete','Slett']] as action}<form method="POST" action="?/moderate"><input type="hidden" name="reportId" value={report.id}/><input type="hidden" name="operation" value={action[0]}/><button class:danger={action[0] === 'delete'} disabled={report.status !== 'open'}>{action[1]}</button></form>{/each}</div></td></tr>{/each}</tbody></table></div>{:else}<div class="empty"><ShieldCheck size={34}/><h2>Rapportkøen er tom</h2><p>Ingen innholdselementer venter på behandling.</p></div>{/if}</section>
    {:else}
      <p class="live-label"><i></i>Live · oppdatert {systemMeasuredAt.toLocaleTimeString('nb-NO')}</p><section class="machine"><header><div><span class="machine-mark">S</span><div><small>Samvio server</small><h2>{liveSystem.hostname}</h2><p>{liveSystem.platform} {liveSystem.release} · {liveSystem.arch}</p></div></div><span class="status good">På nett</span></header><div class="machine-grid"><dl><div><dt>Operativsystem</dt><dd>{liveSystem.platform} {liveSystem.release}</dd></div><div><dt>Arkitektur</dt><dd>{liveSystem.arch}</dd></div><div><dt>Oppetid</dt><dd>{formatUptime(liveSystem.uptimeSeconds)}</dd></div><div><dt>Node.js</dt><dd>{liveSystem.nodeVersion}</dd></div></dl><dl><div><dt>Prosessor</dt><dd>{liveSystem.cpuModel}</dd></div><div><dt>CPU-kjerner</dt><dd>{liveSystem.cpuCount}</dd></div><div><dt>Belastning 1 / 5 / 15 min</dt><dd>{liveSystem.load.map((value: number) => value.toFixed(2)).join(' · ')}</dd></div><div><dt>Samvio-prosess</dt><dd>{formatBytes(liveSystem.processMemory)} RAM</dd></div></dl></div></section>
      <section class="resource-grid"><article class="panel resource"><header><div><Activity size={20}/><h2>Minne</h2></div><strong>{Math.round((liveSystem.memoryTotal - liveSystem.memoryFree) / liveSystem.memoryTotal * 100)}%</strong></header><div class="resource-body"><div class="storage-bar"><i style={`width:${(liveSystem.memoryTotal - liveSystem.memoryFree) / liveSystem.memoryTotal * 100}%`}></i></div><p>{formatBytes(liveSystem.memoryTotal - liveSystem.memoryFree)} brukt · {formatBytes(liveSystem.memoryFree)} ledig · {formatBytes(liveSystem.memoryTotal)} totalt</p></div></article><article class="panel resource"><header><div><HardDrive size={20}/><h2>Disk</h2></div><strong>{liveSystem.diskTotal ? Math.round((liveSystem.diskTotal - liveSystem.diskFree) / liveSystem.diskTotal * 100) : 0}%</strong></header><div class="resource-body"><div class="storage-bar"><i style={`width:${liveSystem.diskTotal ? (liveSystem.diskTotal - liveSystem.diskFree) / liveSystem.diskTotal * 100 : 0}%`}></i></div><p>{formatBytes(liveSystem.diskTotal - liveSystem.diskFree)} brukt · {formatBytes(liveSystem.diskFree)} ledig · {formatBytes(liveSystem.diskTotal)} totalt</p></div></article></section>
      <section class="system-grid"><article class="panel system-card"><HardDrive size={27}/><div><span>Samvio-bilder</span><strong>{formatBytes(data.storage.bytes)}</strong><p>Innlegg, profilbilder og forsidebilder på lokal disk.</p></div></article><article class="panel system-card"><Database size={27}/><div><span>Database</span><strong>Tilkoblet</strong><p>MySQL/MariaDB svarer og dashboarddata er hentet.</p></div></article><article class="panel system-card"><ShieldCheck size={27}/><div><span>Opplastingsgrenser</span><strong>25 MB</strong><p>Bilder komprimeres i nettleseren til omtrent 1–3 MB før sending.</p></div></article></section>
    {/if}
  </section>
</main>

<style>
  :global(body){background:#f4f1ea}.admin-page{--green:#315d49;--green-dark:#234636;--sand:#f4f1ea;--cream:#fffdf9;--line:#ddd8ce;--orange:#b76538;min-height:100vh;color:#1c211e;background:radial-gradient(circle at 85% 0,#e4eee8 0,transparent 34rem),var(--sand)}.admin-nav{position:fixed;inset:0 auto 0 0;width:240px;display:flex;flex-direction:column;padding:28px 16px;border-right:1px solid #d8d4ca;background:#fffdf9eF;backdrop-filter:blur(16px)}.admin-brand{display:flex;align-items:center;gap:11px;padding:0 9px 26px}.admin-brand>span{width:38px;height:38px;display:grid;place-items:center;border-radius:13px 6px 13px 6px;background:linear-gradient(145deg,var(--green),var(--green-dark));color:#fff;font-weight:800}.admin-brand div{display:grid}.admin-brand strong{font:600 24px 'Newsreader',serif}.admin-brand small{color:#7a7e7a;font-size:10px;text-transform:uppercase;letter-spacing:.08em}.admin-nav nav{display:grid;gap:7px}.admin-nav button,.back{display:flex;align-items:center;gap:11px;width:100%;padding:11px 12px;border:0;border-radius:10px;background:transparent;color:#545a56;text-align:left;font-size:13px;font-weight:700}.admin-nav button:hover,.admin-nav button.active{background:#e8f0eb;color:var(--green-dark)}.count{margin-left:auto;min-width:21px;padding:3px 6px;border-radius:999px;background:var(--orange);color:#fff;text-align:center;font-size:9px}.back{margin-top:auto;border:1px solid var(--line)}.admin-content{min-height:100vh;margin-left:240px;padding:34px clamp(22px,4vw,58px) 70px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:26px}.topbar span{color:var(--green);font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.12em}.topbar h1{margin:5px 0 2px;font:600 clamp(30px,4vw,42px) 'Newsreader',serif}.topbar p,.muted{margin:0;color:#737873;font-size:12px}.healthy{display:flex;align-items:center;gap:8px;padding:9px 12px;border:1px solid #cbd9d0;border-radius:999px;background:#f7fbf8;color:var(--green);font-size:11px;font-weight:800}.healthy i{width:7px;height:7px;border-radius:50%;background:#65a37f;box-shadow:0 0 0 4px #e2f0e7}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat-grid article,.panel{border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 10px 28px #26382f0a}.stat-grid article{padding:18px}.stat-grid article>span{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:#e8f0eb;color:var(--green)}.stat-grid article.attention>span{background:#faeee6;color:var(--orange)}.stat-grid p{margin:15px 0 5px;color:#6b706c;font-size:11px}.stat-grid strong{display:block;font:600 31px 'Newsreader',serif}.stat-grid small{color:#979b97;font-size:10px}.overview-grid,.system-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:14px;margin-top:14px}.panel{overflow:hidden}.panel>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 18px;border-bottom:1px solid #ebe7df}.panel>header>div{display:flex;align-items:center;gap:9px}.panel h2{margin:0;font-size:14px}.status,.pill{display:inline-flex;padding:5px 8px;border:1px solid #d8dcd8;border-radius:999px;background:#f7f8f7;color:#5f6561;font-size:9px;font-weight:800}.status.good,.pill.subscriber{border-color:#bdd3c5;background:#e8f3ec;color:var(--green)}.pill.suspended,.row-actions .danger{border-color:#ebc1b9;background:#fff0ed;color:#9b3c2d}.pill.open{border-color:#e8cfad;background:#fff7e9;color:#8c5a21}.status-list{padding:5px 18px}.status-list p{display:flex;justify-content:space-between;margin:0;padding:12px 0;border-bottom:1px solid #efede7;font-size:12px}.status-list span{color:#737873}.panel>.muted{padding:15px 18px}.storage-bar{height:9px;margin:24px 18px 5px;overflow:hidden;border-radius:99px;background:#e9ece9}.storage-bar i{display:block;height:100%;min-width:3px;border-radius:inherit;background:linear-gradient(90deg,var(--green),#73a68a)}.notice{margin-bottom:16px;padding:12px 14px;border-radius:1