low:auto}.admin-nav button{width:auto;flex:none}.back{display:none}.admin-content{margin:0;padding:24px 15px 90px}.stat-grid{grid-template-columns:repeat(2,1fr)}.overview-grid,.system-grid{grid-template-columns:1fr}}@media(max-width:560px){.topbar{align-items:flex-start}.healthy{display:none}.stat-grid{grid-template-columns:1fr 1fr}.stat-grid article{padding:14px}.table-head{align-items:flex-start;flex-direction:column}.table-head form{width:100%}}
  .machine{overflow:hidden;margin-bottom:14px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(135deg,#fff,#f3f8f5);box-shadow:0 10px 28px #26382f0a}.machine>header{display:flex;align-items:center;justify-content:space-between;padding:20px;border-bottom:1px solid #e5e6e1}.machine>header>div{display:flex;align-items:center;gap:13px}.machine-mark{width:48px;height:48px;display:grid;place-items:center;border-radius:16px 7px 16px 7px;background:var(--green);color:#fff;font-size:20px;font-weight:800}.machine h2{margin:2px 0;font:600 24px 'Newsreader',serif}.machine small{color:var(--green);font-size:9px;font-weight:800;text-transform:uppercase;letter-spacing:.1em}.machine p{margin:0;color:#747974;font-size:11px}.machine-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;padding:18px 20px}.machine dl{margin:0}.machine dl>div{display:flex;justify-content:space-between;gap:18px;padding:9px 0;border-bottom:1px solid #e9e9e4;font-size:11px}.machine dt{color:#747974}.machine dd{margin:0;text-align:right;font-weight:700}.resource-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}.resource>header strong{font:600 21px 'Newsreader',serif}.resource-body{padding:4px 0 15px}.resource-body p{margin:8px 18px 0;color:#747974;font-size:10px}@media(max-width:980px){.resource-grid,.machine-grid{grid-template-columns:1fr}.machine-grid{gap:0}}@media(max-width:560px){.machine-grid{padding:13px}.machine>header{padding:15px}}
  .live-label{display:flex;align-items:center;justify-content:flex-end;gap:7px;margin:0 2px 8px;color:#68716b;font-size:10px}.live-label i{width:7px;height:7px;border-radius:50%;background:#68a681;box-shadow:0 0 0 4px #dcece2;animation:pulse 2s infinite}@keyframes pulse{50%{opacity:.45}}
  :global(body){background:#08100c}.admin-page{--sand:#08100c;--cream:#0d1812;--line:#26372d;color:#e8eee9;background:radial-gradient(circle at 87% -10%,#1b3d2c 0,transparent 35rem),radial-gradient(circle at 30% 110%,#3b241a 0,transparent 32rem),#08100c}.admin-nav{border-color:#223229;background:#0b1610ed}.admin-brand strong,.topbar h1,.stat-grid strong,.panel h2,.machine h2,.system-card strong,.empty h2{color:#f2f4f1}.admin-brand small,.topbar p,.muted,.stat-grid p,.stat-grid small,.status-list span,.system-card span,.system-card p,.machine p,.machine dt,.resource-body p,.live-label{color:#91a097}.admin-nav button,.back{color:#aeb9b2}.admin-nav button:hover,.admin-nav button.active{background:#183326;color:#bfe0cb}.back{border-color:#2a3b31}.stat-grid article,.panel,.machine{border-color:var(--line);background:#0e1a14d9;box-shadow:0 16px 38px #0003;backdrop-filter:blur(16px)}.stat-grid article>span{background:#173427;color:#84b899}.stat-grid article.attention>span{background:#41281d;color:#e3a27e}.healthy{border-color:#2d4b3a;background:#10241a;color:#9dd0af}.healthy i{box-shadow:0 0 0 4px #1b3928}.panel>header,.machine>header{border-color:#25362c}.status,.pill{border-color:#36473d;background:#17231c;color:#b2bcb5}.status.good,.pill.subscriber{border-color:#315840;background:#173426;color:#a9d8ba}.pill.suspended,.row-actions .danger{border-color:#63372e;background:#321c18;color:#efaa9d}.pill.open{border-color:#60492e;background:#332817;color:#e9bd7c}.status-list p,.machine dl>div,th,td{border-color:#24342b}.storage-bar{background:#233229}.notice.success{background:#173426;color:#a9d8ba}.notice.error{background:#351e1a;color:#f1aaa0}.table-head form{border-color:#34463b;background:#0a140f}.table-head input{color:#eef3ef}.table-head input::placeholder{color:#718078}.table-head button,.row-actions button,.role-form button{border-color:#355142;background:#172b20;color:#bfe0cb}.role-form select{border-color:#35463c;background:#0d1812;color:#e8eee9}th{background:#101d16;color:#91a097}.type{color:#e29a72}.machine{background:linear-gradient(135deg,#101d16,#0b1510)}.live-label i{box-shadow:0 0 0 4px #183326}.public-empty{background:#0e1a14}
